 "content": "def transform(grid):
    h,w=len(grid),len(grid[0])
    # Recolor/extend from directional boundary bars toward the interior; isolated
    # markers extend along their row/column to the nearer boundary.
    out=[row[:] for row in grid]
    bg=max(set(x for row in grid for x in row),key=lambda x:sum(r.count(x) for r in grid))
    # infer line color as the non-background singleton
    from collections import Counter
    counts=Counter(x for row in grid for x in row if x!=bg)
    line=max((x for x in counts if counts[x]<6),key=lambda x:counts[x],default=None)
    if line is None:return out
    bars=[]
    for r in range(h):
        c=0
        while c<w:
            if grid[r][c]!=bg:
                v=grid[r][c];a=c
                while c<w and grid[r][c]==v:c+=1
                if c-a>=2:bars.append(('h',r,a,c,v))
            else:c+=1
    for r in range(h):
        c=0
        while c<w:
            if grid[r][c]!=bg:
                v=grid[r][c];a=r
                while r<h and grid[r][c]==v:r+=1
                if r-a>=2:bars.append(('v',a,c,a,r,v))
            else:r+=1
    # Treat the paired bars as indications of the output edge rays.
    for typ,r,a,b,v in bars:
        if typ=='h':
            # top-side bar directs rightward; bottom-side bar directs leftward
            direction=1 if r < h//2 else -1
            start=b-1 if direction==1 else a
            rr=r
            for cc in range(start+direction,w if direction==1 else -1,direction):
                if grid[rr][cc]==bg:out[rr][cc]=line
        else:
            direction=1 if a<h//2 else -1
            cc=b
            for rr in range(a+direction,h if direction==1 else -1,direction):
                if grid[rr][cc]==bg:out[rr][cc]=line
    # marker lines follow aligned row/column axes
    for r in range(h):
        for c in range(w):
            if grid[r][c]!=bg and all(not (x<=c<y and rr==r) for t,rr,x,y,v in bars if t=='h') and all(not (x<=r<y and cc==c) for t,x,cc,_,y,v in bars if t=='v'):
                out[r][c]=4
    return out
